#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/git/tasks/code-git-config.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Validate git-config"
# MISE dir="."
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--fix" help="Remove forbidden configs from local git-config"

# This task runs only inside a git hook, so it prints status lines only and no
# header.

import os
import re
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

helpers.print_wait("Validating git-config ... ")

FIXIT = os.environ.get("usage_fix") or "false"

# Forbidden local git config settings
FORBIDDEN = (
  r"user\.name|user\.email|user\.signingkey|commit\.gpgsign|tag\.gpgsign|gpg\.format|gpg\.program|gpg\.ssh\.program"
)

# Forbidden configs that exist in the local git config. A failure of git gives
# an empty list, and its message stays on stderr.
result = subprocess.run(["git", "config", "--local", "--list"], check=False, stdout=subprocess.PIPE, text=True)
LOCAL_CONFIG = [line for line in result.stdout.split("\n") if re.match(rf"^({FORBIDDEN})=", line)]

if LOCAL_CONFIG:
  if FIXIT == "true":
    helpers.print_warn()
    helpers.print_info("Fixing")
    for line in LOCAL_CONFIG:
      key = line.split("=", 1)[0]
      helpers.print_wait(f"- removing {key} ... ")
      unset = subprocess.run(["git", "config", "unset", "--local", key], check=False)
      if unset.returncode != 0:
        sys.exit(unset.returncode)
      helpers.print_success()
    sys.exit(0)
  else:
    helpers.print_error()
    for line in LOCAL_CONFIG:
      helpers.print_warn(f"- {line}")
    task = os.environ.get("MISE_TASK_NAME", "")
    helpers.print_error(f"Please use `mise run {task} --fix` to remove them")
    sys.exit(1)

helpers.print_success()
